const months = ["Janar", "Shkurt", "Mars", "Prill", "Maj", "Qershor", "Korrik", "Gusht", "Shtator", "Tetor", "Nëntor", "Dhjetor"];
const shiftA = { code: "A", start: "07:00", end: "17:00", lunchMin: 60, opGrace: 20 };
const money = (value = 0) => `${new Intl.NumberFormat("sq-AL", { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value / 100)} L`;
const hasPaymentSplit = (entry: any) => entry.bankPaymentCents != null || entry.cashPaymentCents != null ? (entry.bankPaymentCents || 0) !== 0 || (entry.cashPaymentCents || 0) !== 0 : false;
const bankAmount = (entry: any) => hasPaymentSplit(entry) ? entry.bankPaymentCents || 0 : entry.paymentMethod === "BANK" ? entry.payableCents || 0 : 0;
const cashAmount = (entry: any) => hasPaymentSplit(entry) ? entry.cashPaymentCents || 0 : entry.paymentMethod === "CASH" ? entry.payableCents || 0 : 0;
const norm = (value: string) => value.toLocaleLowerCase("sq-AL").replace(/[^a-z0-9ëç]/gi, "");
const samePayrollPerson = (left: string, right: string) => {
  const nameTokens = (value: string) => value.toLocaleLowerCase("sq-AL").replace(/[^a-z0-9ëç\s]/gi, "").split(/\s+/).filter(Boolean);
  const leftParts = nameTokens(left);
  const rightParts = nameTokens(right);
  if (leftParts.length < 2 || rightParts.length < 2) return nameTokens(left).join("") === nameTokens(right).join("");
  return leftParts[0] === rightParts[0] && (leftParts[1] === rightParts[1] || leftParts[1].slice(0, 4) === rightParts[1].slice(0, 4));
};
const superscriptDigits: Record<string, string> = { "0": "⁰", "1": "¹", "2": "²", "3": "³", "4": "⁴", "5": "⁵", "6": "⁶", "7": "⁷", "8": "⁸", "9": "⁹" };
const roundedHours = (minutes = 0) => Math.round(minutes / 60);
const superscriptHours = (minutes = 0) => String(roundedHours(minutes)).replace(/\d/g, digit => superscriptDigits[digit] || digit);
const presenceHourText = (row?: { normalMinutes?: number; overtimeMinutes?: number }) => !row ? "" : `${roundedHours(row.normalMinutes)}${row.overtimeMinutes ? superscriptHours(row.overtimeMinutes) : ""}`;

function PresenceHour({ row }: { row?: { normalMinutes?: number; overtimeMinutes?: number } }) {
  if (!row) return null;
  const normal = roundedHours(row.normalMinutes);
  const overtime = roundedHours(row.overtimeMinutes);
  return <><span>{normal}</span>{overtime > 0 && <sup className="ml-px align-super text-[9px] font-semibold leading-none text-[#2c5282]">{overtime}</sup>}</>;
}

function buildPresenceExportRows(attendance: any[], employees: any[], period?: any, leaves: any[] = [], legendCodes: Array<{ code: string }> = [{ code: "L" }, { code: "M" }, { code: "NM" }, { code: "NV" }]) {
  const days = period ? new Date(period.year, period.month, 0).getDate() : 31;
  const records = new Map(attendance.map(row => [`${row.payrollEmployeeId}-${row.day}`, row]));
  const leaveMap = period ? leaveDaysInPeriod(leaves, period.year, period.month) : new Map();
  return employees.map(employee => {
    const rows = attendance.filter(row => row.payrollEmployeeId === employee.id);
    const { normalMinutes: normal, overtimeMinutes: overtime, grossMinutes: gross, payableMinutes } = payrollPresenceTotals(rows);
    const output: Record<string, string> = { "EMËR MBIEMËR": `${employee.firstName} ${employee.lastName || ""}`.trim() };
    const codeCounts = Object.fromEntries(legendCodes.map(item => [item.code, 0])) as Record<string, number>;
    Array.from({ length: days }, (_, index) => index + 1).forEach(day => {
      const row = records.get(`${employee.id}-${day}`);
      const leave = leaveMap.get(`${employee.id}-${day}`);
      const code = row?.attendanceCode && row.attendanceCode !== "8" ? row.attendanceCode : "";
      if (code && codeCounts[code] !== undefined) codeCounts[code] += 1;
      output[String(day)] = row ? presenceHourText(row) : leave ? leave.leaveType.slice(0, 1).toUpperCase() : "";
    });
    output["O.BRUTO"] = String(roundedHours(gross));
    output["O.PAGESË"] = String(roundedHours(payableMinutes));
    output.NORMALE = String(roundedHours(normal));
    output["SHTESË"] = String(roundedHours(overtime));
    legendCodes.forEach(item => { output[item.code] = String(codeCounts[item.code] || 0); });
    output["TOTAL ORË"] = String(roundedHours(payableMinutes + overtime));
    return output;
  });
}

